using Allocation.Contracts;
using Wolverine.Http;
using Wolverine.Marten;

namespace Allocation.Slices.Allocation;

/// <summary>
/// Opens the limited resource. THE CREATE SLICE, so it starts the stream rather than fetching one:
/// <c>terminal="poolId:generated"</c> says the id is minted here, which means the stream cannot exist yet.
///
/// Its one rule, <c>CapacityMustBePositive</c>, is the model's only <c>enforce="periphery"</c> — the
/// request alone settles it, so it lives in OpenPoolValidator and never reaches this method.
/// </summary>
public static class OpenPoolEndpoint
{
    public const string Route = "/pools";

    public sealed record Opened(Guid PoolId, int Capacity);

    [WolverinePost(Route)]
    public static (Opened, IStartStream) Open(OpenPool command)
    {
        // Honours a supplied id for the same reason ReserveSlotEndpoint does: a test needs to be able to
        // name the pool it is talking about.
        var poolId = command.PoolId == Guid.Empty ? Guid.NewGuid() : command.PoolId;
        var opened = new PoolOpened(poolId, command.Capacity, DateTimeOffset.UtcNow);

        return (new Opened(poolId, command.Capacity),
                MartenOps.StartStream<OpenPoolState>(OpenPoolState.StreamKey(poolId.ToString()), opened));
    }
}
